<script setup lang="ts">
import {ref,computed} from 'vue';import ModalDialog from '../../components/ModalDialog.vue';import type {ResearchFile,EggTaskConfig} from '../../platform/research.ts';
const props=defineProps<{files:ResearchFile[];config:EggTaskConfig;busy:boolean}>();const emit=defineEmits<{close:[];submit:[files:ResearchFile[],config:EggTaskConfig]}>();
const settings=ref({...props.config}),selected=ref(props.files.map(f=>f.id));const all=computed(()=>props.files.length>0&&selected.value.length===props.files.length);
</script>
<template><ModalDialog title="EGG 批量分析" wide @close="emit('close')"><p>处理所选文件的完整滤波信号，单文件选区不带入批次。每个已提交文件独立保存任务与参数，失败项可重试。</p><div class="batch-settings"><label><input v-model="settings.flip_channels" type="checkbox"/>交换 EGG / 音频声道</label><label><input v-model="settings.generate_images" type="checkbox"/>同时导出三张图片</label><label><input v-model="settings.keep_praat_f0" type="checkbox"/>Praat F0</label><label><input v-model="settings.keep_gci_f0" type="checkbox"/>GCI F0</label><label>静音阈值<input v-model.number="settings.silence_threshold" type="number" min="0" max="1" step=".001"/></label><label>高通 Hz<input v-model.number="settings.highpass_cutoff" type="number" min="1" max="47999"/></label><label>GCI<select v-model="settings.gci_method"><option value="slope">斜率</option><option value="scale">尺度</option></select></label><label>GOI<select v-model="settings.goi_method"><option value="scale">尺度</option><option value="slope">斜率</option></select></label></div><p class="hint">静音判断沿用 20 ms 平均绝对振幅，仅遮罩批次 CSV。其余参数继承打开窗口时的页面设置。</p><label><input type="checkbox" :checked="all" :disabled="busy" @change="selected=all?[]:files.map(f=>f.id)"/>全选（{{selected.length}} / {{files.length}}）</label><div class="batch-files"><label v-for="file in files" :key="file.id"><input v-model="selected" type="checkbox" :value="file.id" :disabled="busy"/><span>{{file.name}}</span></label></div><template #footer><button @click="emit('close')">返回工作台</button><button class="primary" :disabled="busy||!selected.length" @click="emit('submit',files.filter(f=>selected.includes(f.id)),settings)">{{busy?'正在提交…':'提交所选文件'}}</button></template></ModalDialog></template>
<style scoped>.batch-settings{display:flex;flex-wrap:wrap;gap:12px;margin:14px 0}.batch-settings label,.batch-files label{display:flex;align-items:center;gap:6px}.batch-settings input[type=number]{width:85px}.batch-files{max-height:260px;overflow:auto;margin-top:12px;border-top:1px solid var(--border)}.batch-files label{padding:6px;border-bottom:1px solid var(--border)}.batch-files span{overflow-wrap:anywhere}</style>
